        if self._config is None:
            self._config = self._try_load_config()
            if self._config is None:
                raise Exception("The reader index isn't defined.")

        if self._config is None or not (self._config.remote_dir or self._config.compressor):
            raise Exception("The configuration is invalid.")

        if self._prepare_thread is None and self._config is not None:
            self._prepare_thread = PrepareChunksThread(
                config=self._config,
                item_loader=self._item_loader,
                distributed_env=self._distributed_env,
                max_cache_size=self._max_cache_size,
