  assert_valid_stepfun(tp, vp)

  result = {i: 0 for i in range(len(t))}
  indices = jnp.searchsorted(t, tp)

  for i in range(len(t)):
    result[i] = jnp.sum(vp[indices[jnp.where(tp >= t[i])] & (tp < t[i + 1])])

  if use_avg:
    widths = t[1:] - t[:-1]
    return jnp.array([value / width for value, width in zip(result.values(), widths)])

